def fitness(metrics):
    # Reward serving more riders while keeping pooling detour tiny.
    # detour_total is the pooling cost this skill exists to suppress;
    # completed rewards the amortised extra riders actually delivered.
    comp = metrics['completed']
    detour = metrics['detour_total']
    return comp / (1.0 + detour / 1000.0)

